<?php
/**
 * Drivew - Global application configuration.
 * Generated by the installer. Do NOT edit manually after install.
 * Edit this file (or the admin Settings page) to change app-level constants.
 */

// Application-level constants
define('APP_NAME', 'Drivew');

// Base URL: the web root + /Drive. Auto-detect when running locally so the
// app works under XAMPP, cPanel subfolders, or root without editing this file.
// A relative base works for all asset/links; set absolute only if needed.
define('APP_BASE', '');

// Where physical uploads live (absolute path, no trailing slash)
define('UPLOAD_ROOT', dirname(__DIR__) . '/uploads');

// Where the installer lock file lives (used to block re-runs)
define('INSTALL_LOCK', dirname(__DIR__) . '/install.lock');

// Where audit / error logs are written
define('LOG_DIR', dirname(__DIR__) . '/logs');

// Default maximum upload size in bytes (used as a ceiling; per-user quota also applies)
define('MAX_UPLOAD_BYTES', 104857600); // 100 MB

// Maximum number of file versions to retain per file
define('MAX_VERSIONS', 10);

// Session name (unique to avoid collision with other apps on the same host)
define('SESSION_NAME', 'drivew_sid');

// Timezone - keep in sync with the server or override here.
date_default_timezone_set('UTC');

error_reporting(E_ALL);
ini_set('display_errors', '0');
ini_set('log_errors', '1');
if (is_dir(LOG_DIR)) {
    ini_set('error_log', LOG_DIR . '/php_error.log');
}

/**
 * Ensure session starts exactly once with secure flags.
 * Idempotent - safe to call from every entry point.
 */
function drivew_start_session(): void
{
    if (session_status() === PHP_SESSION_ACTIVE) {
        return;
    }
    session_name(SESSION_NAME);
    session_set_cookie_params([
        'lifetime' => 0,
        'path'     => '/',
        'domain'   => '',
        'secure'   => !empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off',
        'httponly' => true,
        'samesite' => 'Lax',
    ]);
    session_start();
}

drivew_start_session();
